insert into public.decisions
  (number, statement, reason, status, decided_by_name, decided_at, origin, origin_ref)
overriding system value
values
  (205, 'Answers G12, G13, G14 and the new G19. G12: when two people''s direction conflicts, the named owner of the area decides, and the owner of the project (`FALLBACK_OWNER`) for anything in no area or an area with no owner; until they do, the active decision stands. G19: an area is a name, one owner, optional code paths (globs, like CODEOWNERS) and words that mark it in text; anyone signed in may create one or change it, every change kept with who and when. G13: the bot only briefs; it never acts for a person in a shared space. Everyone who has written to the bot, owns an area or is waited on gets one direct message a day, and may say "stop briefs". G14: tasks reach the web app through a small interface in the API with two providers, Jira (its REST API, with a credential of the API''s own) and a built-in tracker; a team uses one; the agent keeps its own Atlassian tools', 'Chosen in conversation, all as recommended', 'active', 'the owner', '2026-11-25T00:00:00Z', 'import', '205'),
  (206, 'Wave 3 is planned in `wave-3.md`: areas, owners and routing (3.1), conflict surfacing (3.2), tasks and the waiting-on list (3.3), daily briefs by direct message (3.4), in that order, 3.2 and 3.3 side by side. Slice 3.1 is planned in `slice-3-1.md`: an `areas` table with owners, paths and words, kept with its history; a brief, a pull request or a proposed decision that touches an area names its owner in the thread, once per change and area; the owner of a decision''s area may confirm, reject or reword it, beside those who wrote in its thread (G11 from 3.1); `GET /v1/people` from the record for choosing owners. No model runs to match areas', 'Asked for in conversation: "let''s do it" (plan wave 3). Matching words and paths is cheap, predictable and explainable; a mention in the thread tells the owner without the direct messages of 3.4', 'active', 'the owner', '2026-11-25T00:00:00Z', 'import', '206')
on conflict (origin, origin_ref) where origin_ref is not null do nothing;
